Read M3 and N5 from the data sheet, parse the mixed date formats in column A, and sum K2:K32 for rows whose name contains M3 and whose date equals N5.  
Write the rounded total to data!O3 only.  
Save the workbook without adding sheets or altering other cells.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta
from decimal import Decimal, ROUND_HALF_UP

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["data"]
vws = vals["data"]

def parse_date(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, (int, float)):
        try:
            if v > 59:
                return (datetime(1899, 12, 30) + timedelta(days=float(v))).date()
        except Exception:
            pass
        return None

    s = str(v).strip().replace("T", " ")
    if not s:
        return None
    s = s.split(" ")[0]

    formats = (
        "%m-%d-%y",
        "%m/%d/%y",
        "%Y-%m-%d",
        "%m-%d-%Y",
        "%m/%d/%Y",
        "%d-%m-%y",
        "%d/%m/%y",
        "%d-%m-%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
    )
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    return None

def time_to_hours(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.hour + v.minute / 60 + v.second / 3600 + v.microsecond / 3600000
    if hasattr(v, "hour") and hasattr(v, "minute") and not isinstance(v, datetime):
        return v.hour + v.minute / 60 + v.second / 3600 + getattr(v, "microsecond", 0) / 3600000
    if isinstance(v, (int, float)):
        x = float(v)
        if 0 <= x < 1:
            return x * 24
        return x

    s = str(v).strip()
    if not s:
        return None

    for fmt in ("%H:%M:%S", "%H:%M", "%I:%M:%S %p", "%I:%M %p"):
        try:
            t = datetime.strptime(s, fmt).time()
            return t.hour + t.minute / 60 + t.second / 3600 + t.microsecond / 3600000
        except ValueError:
            pass

    try:
        return float(s)
    except ValueError:
        return None

def round6(x):
    if abs(x) < 1e-12:
        return 0.0
    return float(Decimal(str(x)).quantize(Decimal("0.000001"), rounding=ROUND_HALF_UP))

mechanic = vws["M3"].value
start_date = parse_date(vws["N5"].value)
mechanic_str = str(mechanic).strip().lower() if mechanic is not None else ""

total = 0.0
matched = 0

for r in range(2, 33):
    name = vws.cell(row=r, column=3).value
    d = vws.cell(row=r, column=1).value
    k = vws.cell(row=r, column=11).value

    if name is None or d is None:
        continue
    if mechanic_str and str(name).strip().lower().find(mechanic_str) == -1:
        continue
    if start_date is None or parse_date(d) != start_date:
        continue

    try:
        kval = float(k)
    except (TypeError, ValueError):
        e = time_to_hours(vws.cell(row=r, column=5).value)
        f = time_to_hours(vws.cell(row=r, column=6).value)
        if e is None or f is None:
            continue
        kval = f - e
        if kval < 0:
            kval += 24

    total += kval
    matched += 1

ws["O3"] = round6(total)
wb.save(OUT)

print("start_date:", start_date)
print("mechanic:", mechanic_str)
print("matched_rows:", matched)
print("O3:", ws["O3"].value)
